pub fn is_prime(n: i8) -> bool {
    // By definition, primes are integers >= 2 with no divisors in [2, n).
    if n < 2 {
        return false;
    }

    // Work in a wider type to avoid any potential overflow issues.
    let nn = n as i16;

    // Loop candidate divisors k from 2 up to (but not including) n.
    let mut k: i16 = 2;
    while k < nn {
        if nn % k == 0 {
            return false;
        }
        k += 1;
    }

    true
}